cards.solution:
class Rekening:
    def __init__(self):
        self.saldo = 0

    def setor(self, n):
        self.saldo += n

    def tarik(self, n):
        if n > self.saldo:
            raise ValueError("saldo kurang")
        self.saldo -= n

r = Rekening()
for _ in range(int(input())):
    aksi, n = input().split()
    try:
        if aksi == "setor":
            r.setor(int(n))
        else:
            r.tarik(int(n))
        print(r.saldo)
    except ValueError:
        print("Saldo kurang")

